use std::cmp::Ordering;
fn cmp(a:&(&str,usize), b:&(&str,usize), sels:&[&str]) -> Ordering {
    for s in sels {
        if a.0 == *s { return Ordering::Less; }
        if b.0 == *s { return Ordering::Greater; }
    }
    Ordering::Equal
}
fn main(){
 let cases = vec![
  (vec!["A","B","A","B"], vec!["B","A"]),
  (vec!["A","B","A","AB","B"], vec!["B","A"]),
  (vec!["A","B","A","AB","B"], vec!["AB","B","A"]),
  (vec!["A","B","C","A","B","C"], vec!["B","A"]),
  (vec!["B","A","B","A"], vec!["A","B"]),
  (vec!["X","A","B","A","B","X"], vec!["X","B","A"]),
 ];
 for (hdr,sels) in cases { let mut v:Vec<_>=hdr.iter().enumerate().filter(|(_,h)| sels.contains(h)).map(|(i,h)| (*h,i+1)).collect(); let mut u=v.clone(); v.sort_by(|a,b| cmp(a,b,&sels)); u.sort_unstable_by(|a,b| cmp(a,b,&sels)); println!("hdr {:?} sels {:?} stable {:?} unstable {:?}", hdr,sels,v,u); }
}
RS
rustc /tmp/badsort.rs -o /tmp/badsort && /tmp/badsort"}

